// ─────────────────────────────────────────────────────────────
// 유틸: 풀네임 → 짧은 표기 (마지막 1~2토큰)
// ─────────────────────────────────────────────────────────────
function shortName(full) {
  const t = full.split(" ");
  if (t.length >= 2) return t.slice(-2).join(" ");
  return full;
}
